49: /** Last id segment, lowercased, separators stripped — for robust matching. */
50: function builtinKey(id: string): string {
51:   const seg = id.includes(":") ? id.slice(id.indexOf(":") + 1) : id;
52:   return seg.toLowerCase().replace(/[-_\s]/g, "");
53: }
54: 
55: function isCwdDependentBuiltin(cap: CapabilityDescriptor): boolean {
56:   return CWD_DEPENDENT_BUILTINS.has(builtinKey(cap.id));
57: }
